import { useCallback, useMemo, useRef } from 'react';
import type { NodeType, NodeId } from '@hierarchidb/common-types';
import { getWorkerBridge } from '@hierarchidb/ui-worker-client';
import { notify } from '@hierarchidb/components';
import { getWorkerClientHook, type WorkerClientRef } from '@hierarchidb/ui-worker-provider';
import type { BuildStatus } from '@hierarchidb/components';
import type { ShapeEntity } from '../../../common/types/index.js';
import { metadataLoader } from '../../../services/metadata/MetadataLoader.js';
import { SAMPLE_COUNTRIES } from '../../../common/mock/data.js';
import { deriveUrlMetadataFromSelection } from '../../utils/selectionUrlMetadata.js';
import { normalizeDataSourceName } from '../../../services/utils/utils.js';

type Args = {
  nodeType: NodeType;
  nodeId?: NodeId;
  sessionId?: string | null;
  data?: Partial<ShapeEntity>;
  onChange: (patch: Partial<ShapeEntity>) => void;
  buildStatus: BuildStatus;
};

export const useBatchSessionActions = ({
  nodeType,
  nodeId,
  sessionId,
  data,
  onChange,
  buildStatus,
}: Args) => {
  const bridgeRef = useRef(getWorkerBridge());
  const workerClientHook = useMemo(() => {
    try {
      return getWorkerClientHook<WorkerClientRef | null>();
    } catch {
      return null;
    }
  }, []);
  const workerClient = workerClientHook ? workerClientHook() : null;

  const saveDraftBeforeBatch = useCallback(async () => {
    if (!nodeId) {
      notify.warning('NodeId is missing.');
      return false;
    }
    if (!workerClient) {
      notify.error('Worker client is unavailable.');
      return false;
    }
    let nextUrlMetadata = data?.urlMetadata;
    if (!nextUrlMetadata || nextUrlMetadata.length === 0) {
      const dataSource = normalizeDataSourceName(
        data?.batchConfig?.dataSource ?? data?.dataSourceName,
      );
      if (!dataSource) {
        notify.warning('Data source is missing.');
        return false;
      }
      try {
        const metadata = await metadataLoader.loadMetadata(dataSource);
        const fallbackMetadata = metadata.length ? metadata : SAMPLE_COUNTRIES;
        nextUrlMetadata = deriveUrlMetadataFromSelection({
          dataSource,
          checkboxState: data?.checkboxState,
          metadata: fallbackMetadata,
        });
        if (!nextUrlMetadata.length) {
          notify.warning('No URL metadata is available for the current selection.');
          return false;
        }
        onChange({ urlMetadata: nextUrlMetadata });
      } catch (error) {
        console.error('[ShapeBuildProgressStep] urlMetadata generation failed', error);
        notify.error('Failed to build urlMetadata for the current selection.');
        return false;
      }
    }
    try {
      const api = workerClient.getAPI();
      const updater = await api.getTreeNodeUpdaterAPI();
      await updater.updateTreeNode(nodeId, {
        mode: 'save-draft',
        draftData: {
          ...(data ?? {}),
          urlMetadata: nextUrlMetadata,
        } as Record<string, unknown>,
      });
      return true;
    } catch (error) {
      notify.error('Failed to save draft.');
      console.error('[ShapeBuildProgressStep] save draft failed', error);
      return false;
    }
  }, [data, nodeId, onChange, workerClient]);

  const handleStartOrResume = useCallback(async () => {
    if (!nodeId) {
      notify.warning('NodeId is missing.');
      return;
    }
    const saved = await saveDraftBeforeBatch();
    if (!saved) return;
    try {
      await bridgeRef.current.initialize();
      if (buildStatus === 'paused' && sessionId) {
        await bridgeRef.current.resumeBatchSession(nodeType, sessionId);
        return;
      }
      const statusResult = await bridgeRef.current.startBatchSession(nodeType, nodeId);
      if (statusResult?.sessionId) {
        onChange({ batchSessionId: statusResult.sessionId });
      }
    } catch (error) {
      notify.error('Failed to start or resume build.');
      console.error('[ShapeBuildProgressStep] start/resume failed', error);
    }
  }, [buildStatus, nodeId, nodeType, onChange, saveDraftBeforeBatch, sessionId]);

  const handlePause = useCallback(async () => {
    if (!sessionId) {
      notify.warning('SessionId is missing.');
      return;
    }
    const saved = await saveDraftBeforeBatch();
    if (!saved) return;
    try {
      await bridgeRef.current.initialize();
      await bridgeRef.current.pauseBatchSession(nodeType, sessionId);
    } catch (error) {
      notify.error('Failed to pause build.');
      console.error('[ShapeBuildProgressStep] pause failed', error);
    }
  }, [nodeType, saveDraftBeforeBatch, sessionId]);

  return {
    handleStartOrResume,
    handlePause,
  };
};
